<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { call } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'
import { useListPersistence } from '../composables/useListPersistence'

const route = useRoute()
const router = useRouter()

// Buka detail; teruskan status terkunci agar tombol back kembali ke filter sama.
function goToDetail(docName) {
	router.push({
		name: 'TargetRealisasiDetail',
		params: { name: docName },
		query: lockedStatus.value ? { status: lockedStatus.value } : undefined,
	})
}

// Status terkunci dari query (?status=...). Tiap menu Coll mengarah ke halaman ini
// dengan status berbeda; tanpa status = tampil semua. Selalu ikut di setiap fetch.
const lockedStatus = computed(() => String(route.query.status || ''))
const listPersistence = useListPersistence(() => `TargetRealisasi:status=${lockedStatus.value}`)
const groupPersistence = useListPersistence(
	() => `TargetRealisasi:status=${lockedStatus.value}:collapsible`,
)

// Judul halaman mengikuti status terpilih.
const STATUS_TITLE = {
	'GAGAL BAYAR': 'Target dan Realisasi Gagal Bayar',
	PARTIAL: 'Target dan Realisasi Partial',
	TARIKAN: 'Target dan Realisasi Tarikan',
	DONE: 'Target dan Realisasi Done',
}
const pageTitle = computed(() => STATUS_TITLE[lockedStatus.value] || 'Target dan Realisasi')

// Field yang diambil untuk card list (name = id_no_perjanjian otomatis ikut).
const LIST_FIELDS = [
	'name',
	'nama_nasabah',
	'status',
	'nopol',
	'bucket',
	'jto_tertunggak',
	'pic_collector',
	'total_tunggakan',
	'sumber',
]

// Opsi filter dibaca dari META doctype, bukan ditulis ulang di sini — begitu
// opsi Select di "Target dan Realisasi" diubah di Frappe (tambah bucket baru,
// ganti nama status, dst), daftar di app ikut berubah tanpa menyentuh kode.
// Nilai di bawah hanya cadangan bila meta gagal dimuat, supaya filter tidak
// mendadak kosong.
const DOCTYPE = 'Target dan Realisasi'
const selectOptions = ref({})
function optionsOf(fieldname, fallback) {
	const v = selectOptions.value[fieldname]
	return v && v.length ? v : fallback
}
const STATUS_LIST = computed(() =>
	optionsOf('status', ['GAGAL BAYAR', 'PARTIAL', 'TARIKAN', 'DONE', 'BELUM JTO']),
)
const SUMBER_LIST = computed(() => optionsOf('sumber', ['KSP', 'JG']))
const BUCKET_LIST = computed(() => optionsOf('bucket', []))

// Ambil opsi tiap field Select dari meta doctype (endpoint yang sama dipakai desk).
async function loadDoctypeMeta() {
	try {
		const res = await fetch(
			`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(DOCTYPE)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } },
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		const docs = json.docs || json.message?.docs || []
		const meta = docs.find((x) => x.name === DOCTYPE) || docs[0]
		const out = {}
		for (const f of (meta && meta.fields) || []) {
			if (f.fieldtype === 'Select' && f.options) {
				out[f.fieldname] = f.options.split('\n').filter(Boolean)
			}
		}
		selectOptions.value = out
	} catch (e) {
		/* meta gagal → pakai nilai cadangan di atas */
	}
}

// Opsi PIC Collector tidak ada di meta (field Select-nya diisi dinamis, sama
// seperti di desk) → diambil dari endpoint yang sumbernya Mapping Collector aktif.
const PIC_LIST = ref([])
async function loadPicOptions() {
	try {
		PIC_LIST.value =
			(await call('juragan.api.portal.target_realisasi.get_pic_collector_options')) || []
	} catch (e) {
		PIC_LIST.value = []
	}
}

// ---- Sort (tanggal JTO saja) ------------------------------------------------
// Satu-satunya sort adalah tanggal JTO; tombol di header langsung toggle ASC/DESC.
// Murni di sisi client (data sudah dimuat semua) sehingga instan tanpa fetch ulang.
const sortDir = ref('asc')
const listEl = ref(null) // container scroll list

function toggleSort() {
	sortDir.value = sortDir.value === 'asc' ? 'desc' : 'asc'
	listPersistence.writePreferences({ sortDir: sortDir.value })
	renderLimit.value = RENDER_STEP
	if (listEl.value) listEl.value.scrollTop = 0
}

// ---- Data (dimuat semua secara bertahap) ------------------------------------
// Seluruh baris diambil berantai per CHUNK agar grup per tanggal langsung lengkap
// dan sort cukup dibalik di client. fetchGen menandai stream aktif: reload()
// menaikkan gen sehingga stream lama yang masih jalan berhenti sendiri.
const CHUNK = 200
const rows = ref([])
const total = ref(null) // total dokumen (untuk indikator progres)
const loading = ref(false) // menunggu batch pertama
const loadingMore = ref(false) // batch lanjutan di latar belakang
const error = ref('')
let fetchGen = 0

// ---- Render bertahap (windowing) ---------------------------------------------
// Data lengkap ada di memori, tapi DOM hanya merender renderLimit card pertama;
// bertambah saat scroll mendekati bawah. Tanpa ini, render 1000+ card sekaligus
// membuat toggle sort dan scroll terasa berat.
const RENDER_STEP = 60
const renderLimit = ref(RENDER_STEP)

function onListScroll() {
	const el = listEl.value
	if (!el) return
	// Selesai bila semua header grup tampil dan semua card grup terbuka sudah dirender.
	const done =
		visibleGroups.value.length >= groups.value.length &&
		expandedCardCount.value <= renderLimit.value
	if (done) return
	if (el.scrollTop + el.clientHeight >= el.scrollHeight - 600) {
		renderLimit.value += RENDER_STEP
	}
}

// ---- Grup per tanggal JTO ---------------------------------------------------
// Card dikelompokkan berdasarkan ANGKA TANGGAL jto_tertunggak saja (1–31),
// lintas bulan/tahun. Dokumen tanpa JTO dikumpulkan di grup terakhir.
function jtoDay(v) {
	if (!v) return null
	const day = Number(String(v).slice(8, 10))
	return Number.isInteger(day) && day >= 1 ? day : null
}

// Grouping + sort naik dihitung sekali per perubahan data.
const groupsAsc = computed(() => {
	const byDay = new Map()
	const noJto = []
	for (const row of rows.value) {
		const day = jtoDay(row.jto_tertunggak)
		if (day == null) noJto.push(row)
		else if (byDay.has(day)) byDay.get(day).push(row)
		else byDay.set(day, [row])
	}
	const result = [...byDay.entries()]
		.sort((a, b) => a[0] - b[0])
		.map(([day, items]) => ({
			key: String(day),
			day,
			count: items.length,
			// Di dalam grup urut berdasarkan tanggal JTO lengkap (bulan/tahun ikut);
			// seri dipecah dengan No Perjanjian.
			items: items.sort(
				(a, b) =>
					String(a.jto_tertunggak).localeCompare(String(b.jto_tertunggak)) ||
					String(a.name).localeCompare(String(b.name)),
			),
		}))
	if (noJto.length)
		result.push({ key: 'tanpa-jto', day: null, count: noJto.length, items: noJto })
	return result
})

// Arah sort tinggal membalik hasil asc (tanpa sort ulang) — toggle jadi instan.
// Grup Tanpa JTO selalu di paling bawah.
const groups = computed(() => {
	if (sortDir.value === 'asc') return groupsAsc.value
	const withDay = []
	let noJto = null
	for (const g of groupsAsc.value) {
		if (g.day == null) noJto = g
		else withDay.push({ ...g, items: [...g.items].reverse() })
	}
	withDay.reverse()
	if (noJto) withDay.push(noJto)
	return withDay
})

// ---- Buka/tutup grup ----------------------------------------------------------
// Set berisi key grup yang TERBUKA; default kosong = semua grup tertutup. Key
// stabil ('1'..'31', 'tanpa-jto') sehingga state bertahan saat toggle sort
// maupun data bertambah.
const expandedKeys = ref(new Set())

function restoreExpandedGroups() {
	const saved = groupPersistence.readSession({ expandedKeys: [] })
	const validKeys = saved.expandedKeys.filter(
		(key) =>
			key === 'tanpa-jto' ||
			(/^\d{1,2}$/.test(key) && Number(key) >= 1 && Number(key) <= 31),
	)
	expandedKeys.value = new Set(validKeys)
}

function toggleGroup(key) {
	const next = new Set(expandedKeys.value)
	if (next.has(key)) next.delete(key)
	else next.add(key)
	expandedKeys.value = next
	groupPersistence.writeSession({ expandedKeys: [...next] })
}

// Jumlah card pada grup yang terbuka — dasar perhitungan jatah render.
const expandedCardCount = computed(() =>
	groups.value.reduce((n, g) => n + (expandedKeys.value.has(g.key) ? g.count : 0), 0),
)

// Potongan yang benar-benar dirender: renderLimit card pertama sesuai urutan grup.
// Grup tertutup hanya menampilkan header (tak memakan jatah); grup terakhir boleh
// terpotong — sisanya muncul saat scroll (onListScroll).
const visibleGroups = computed(() => {
	let budget = renderLimit.value
	const out = []
	for (const g of groups.value) {
		if (budget <= 0) break
		if (!expandedKeys.value.has(g.key)) {
			out.push({ ...g, items: [], collapsed: true })
		} else if (g.items.length <= budget) {
			out.push(g)
			budget -= g.items.length
		} else {
			out.push({ ...g, items: g.items.slice(0, budget) })
			budget = 0
		}
	}
	return out
})

// ---- Filter (bottom-sheet) ------------------------------------------------
function blankFilter() {
	return {
		name: '',
		nama_nasabah: '',
		nopol: '',
		pic_collector: [],
		status: [],
		sumber: [],
		bucket: [],
		tanggal_dari: '',
		tanggal_sampai: '',
	}
}
const filterDraft = reactive(blankFilter()) // working copy saat sheet terbuka
const appliedFilter = reactive(blankFilter()) // yang sudah diterapkan ke query

const activeFilterCount = computed(() => {
	const f = appliedFilter
	let n = 0
	if (f.name.trim()) n++
	if (f.nama_nasabah.trim()) n++
	if (f.nopol.trim()) n++
	if (f.pic_collector.length) n++
	if (f.status.length) n++
	if (f.sumber.length) n++
	if (f.bucket.length) n++
	if (f.tanggal_dari || f.tanggal_sampai) n++
	return n
})

// Filter AND yang dikirim ke get_list.
function buildFilters() {
	const arr = []
	const f = appliedFilter
	if (f.name.trim()) arr.push(['name', 'like', `%${f.name.trim()}%`])
	if (f.nama_nasabah.trim()) arr.push(['nama_nasabah', 'like', `%${f.nama_nasabah.trim()}%`])
	if (f.nopol.trim()) arr.push(['nopol', 'like', `%${f.nopol.trim()}%`])
	if (f.pic_collector.length) arr.push(['pic_collector', 'in', [...f.pic_collector]])
	if (f.status.length) arr.push(['status', 'in', [...f.status]])
	if (f.sumber.length) arr.push(['sumber', 'in', [...f.sumber]])
	if (f.bucket.length) arr.push(['bucket', 'in', [...f.bucket]])
	if (f.tanggal_dari && f.tanggal_sampai)
		arr.push(['jto_tertunggak', 'between', [f.tanggal_dari, f.tanggal_sampai]])
	else if (f.tanggal_dari) arr.push(['jto_tertunggak', '>=', f.tanggal_dari])
	else if (f.tanggal_sampai) arr.push(['jto_tertunggak', '<=', f.tanggal_sampai])
	// Status terkunci dari query (menu varian) — selalu ikut.
	if (lockedStatus.value) arr.push(['status', '=', lockedStatus.value])
	return arr
}

function fetchChunk(start, filters) {
	return call('frappe.client.get_list', {
		doctype: 'Target dan Realisasi',
		filters,
		fields: JSON.stringify(LIST_FIELDS),
		// Urutan total yang STABIL & deterministik antar chunk (name unik) — wajib
		// agar paginasi limit_start/limit_page_length tidak melompati/menduplikasi
		// baris. Pengelompokan per angka tanggal JTO dilakukan di klien (groupsAsc),
		// jadi order_by server tidak perlu fungsi SQL (DAY() ditolak Frappe baru).
		order_by: 'jto_tertunggak asc, name asc',
		limit_start: start,
		limit_page_length: CHUNK,
	})
}

async function reload() {
	const gen = ++fetchGen
	error.value = ''
	loading.value = true
	loadingMore.value = false
	total.value = null
	renderLimit.value = RENDER_STEP
	if (listEl.value) listEl.value.scrollTop = 0

	const andF = buildFilters()
	const filters = andF.length ? JSON.stringify(andF) : undefined

	try {
		// Batch pertama + total diambil bersamaan; total dipakai untuk indikator
		// progres dan menentukan posisi chunk sisanya.
		const [first, count] = await Promise.all([
			fetchChunk(0, filters),
			call('frappe.client.get_count', {
				doctype: 'Target dan Realisasi',
				filters,
			}).catch(() => null),
		])
		if (gen !== fetchGen) return // sudah ada reload baru → berhenti
		if (count != null) total.value = count
		rows.value = first || []
		loading.value = false

		let lastFull = (first || []).length === CHUNK

		// Sisa chunk diambil paralel per gelombang kecil supaya cepat
		// tanpa membanjiri server.
		if (lastFull && count != null && count > CHUNK) {
			loadingMore.value = true
			const starts = []
			for (let s = CHUNK; s < count; s += CHUNK) starts.push(s)
			const WAVE = 4
			for (let i = 0; i < starts.length; i += WAVE) {
				const batches = await Promise.all(
					starts.slice(i, i + WAVE).map((s) => fetchChunk(s, filters)),
				)
				if (gen !== fetchGen) return
				rows.value = rows.value.concat(...batches.map((b) => b || []))
				lastFull = (batches[batches.length - 1] || []).length === CHUNK
			}
		}

		// Lanjut berantai bila total tidak diketahui atau data bertambah sejak count.
		while (lastFull) {
			loadingMore.value = true
			const batch = await fetchChunk(rows.value.length, filters)
			if (gen !== fetchGen) return
			rows.value = rows.value.concat(batch || [])
			lastFull = (batch || []).length === CHUNK
		}
		loadingMore.value = false
	} catch (err) {
		if (gen !== fetchGen) return
		error.value = err?.messages?.[0] || err?.message || String(err)
		loading.value = false
		loadingMore.value = false
	}
}

// Hentikan stream yang masih berjalan saat meninggalkan halaman.
onUnmounted(() => {
	fetchGen++
})

// Status berubah (pindah antar menu Coll tanpa unmount) → pulihkan konteksnya.
watch(lockedStatus, () => {
	restoreTargetState()
	restoreExpandedGroups()
	reload()
})

const showFilterSheet = ref(false)
const showStatusSheet = ref(false)
const showBucketSheet = ref(false)
const showPicSheet = ref(false)

function openFilter() {
	Object.assign(filterDraft, {
		...appliedFilter,
		status: [...appliedFilter.status],
		sumber: [...appliedFilter.sumber],
		bucket: [...appliedFilter.bucket],
		pic_collector: [...appliedFilter.pic_collector],
	})
	showFilterSheet.value = true
}
function toggleStatusDraft(s) {
	const i = filterDraft.status.indexOf(s)
	if (i === -1) filterDraft.status.push(s)
	else filterDraft.status.splice(i, 1)
}
const bucketSummary = computed(() => {
	const n = filterDraft.bucket.length
	if (!n) return ''
	if (n === 1) return filterDraft.bucket[0]
	return `${filterDraft.bucket[0]} +${n - 1}`
})
function toggleBucketDraft(s) {
	const i = filterDraft.bucket.indexOf(s)
	if (i === -1) filterDraft.bucket.push(s)
	else filterDraft.bucket.splice(i, 1)
}
const picSummary = computed(() => {
	const n = filterDraft.pic_collector.length
	if (!n) return ''
	if (n === 1) return filterDraft.pic_collector[0]
	return `${filterDraft.pic_collector[0]} +${n - 1}`
})
function togglePicDraft(s) {
	const i = filterDraft.pic_collector.indexOf(s)
	if (i === -1) filterDraft.pic_collector.push(s)
	else filterDraft.pic_collector.splice(i, 1)
}
function toggleSumberDraft(s) {
	const i = filterDraft.sumber.indexOf(s)
	if (i === -1) filterDraft.sumber.push(s)
	else filterDraft.sumber.splice(i, 1)
}
const statusSummary = computed(() => {
	const n = filterDraft.status.length
	if (!n) return ''
	if (n === 1) return filterDraft.status[0]
	return `${filterDraft.status[0]} +${n - 1}`
})
function applyFilter() {
	Object.assign(appliedFilter, {
		...filterDraft,
		status: [...filterDraft.status],
		sumber: [...filterDraft.sumber],
		bucket: [...filterDraft.bucket],
		pic_collector: [...filterDraft.pic_collector],
	})
	listPersistence.writeSession({ filters: appliedFilter })
	showFilterSheet.value = false
	reload()
}
function clearFilter() {
	Object.assign(filterDraft, blankFilter())
	Object.assign(appliedFilter, blankFilter())
	listPersistence.clearSession()
	showFilterSheet.value = false
	reload()
}

// ---- Kalender rentang JTO Tertunggak --------------------------------------
const showDateSheet = ref(false)
const calCursor = ref(new Date()) // bulan yang ditampilkan (tgl 1)
const rangeStart = ref('') // 'YYYY-MM-DD'
const rangeEnd = ref('')

const WEEKDAYS = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']
const MONTHS = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]

// Format lokal 'YYYY-MM-DD' (hindari pergeseran zona waktu dari toISOString).
function ymd(d) {
	const m = String(d.getMonth() + 1).padStart(2, '0')
	const day = String(d.getDate()).padStart(2, '0')
	return `${d.getFullYear()}-${m}-${day}`
}
function parseYmd(s) {
	const [y, m, d] = String(s).split('-').map(Number)
	return new Date(y, (m || 1) - 1, d || 1)
}

const dateSummary = computed(() => {
	const a = filterDraft.tanggal_dari
	const b = filterDraft.tanggal_sampai
	if (a && b) return `${formatDate(a)} – ${formatDate(b)}`
	if (a) return `Dari ${formatDate(a)}`
	if (b) return `Sampai ${formatDate(b)}`
	return ''
})

function openDateSheet() {
	rangeStart.value = filterDraft.tanggal_dari
	rangeEnd.value = filterDraft.tanggal_sampai
	const base = filterDraft.tanggal_dari || ymd(new Date())
	const d = parseYmd(base)
	calCursor.value = new Date(d.getFullYear(), d.getMonth(), 1)
	showDateSheet.value = true
}

const calLabel = computed(
	() => `${MONTHS[calCursor.value.getMonth()]} ${calCursor.value.getFullYear()}`,
)

const calDays = computed(() => {
	const year = calCursor.value.getFullYear()
	const month = calCursor.value.getMonth()
	const first = new Date(year, month, 1)
	const startOffset = (first.getDay() + 6) % 7 // Senin = 0
	const daysInMonth = new Date(year, month + 1, 0).getDate()
	const cells = []
	for (let i = 0; i < startOffset; i++) cells.push(null)
	for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d))
	return cells
})

function prevMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() - 1, 1)
}
function nextMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() + 1, 1)
}

function pickDay(date) {
	const s = ymd(date)
	if (!rangeStart.value || (rangeStart.value && rangeEnd.value)) {
		rangeStart.value = s
		rangeEnd.value = ''
	} else if (s < rangeStart.value) {
		rangeEnd.value = rangeStart.value
		rangeStart.value = s
	} else {
		rangeEnd.value = s
	}
}

function dayClass(date) {
	const s = ymd(date)
	const isStart = s === rangeStart.value
	const isEnd = s === rangeEnd.value
	if (isStart || isEnd) return 'rounded-full bg-primary font-semibold text-ui-onPrimary'
	if (rangeStart.value && rangeEnd.value && s > rangeStart.value && s < rangeEnd.value)
		return 'rounded-md bg-primary/10 text-primary'
	if (s === ymd(new Date())) return 'rounded-full font-semibold text-primary'
	return 'rounded-full text-ui-ink-gray-700 hover:bg-ui-surface-gray-100'
}

function clearDateRange() {
	rangeStart.value = ''
	rangeEnd.value = ''
}
function applyDateRange() {
	filterDraft.tanggal_dari = rangeStart.value
	filterDraft.tanggal_sampai = rangeEnd.value
	showDateSheet.value = false
}

// ---- Util -----------------------------------------------------------------
// Tanggal "dd Mmm yyyy" (id-ID); kembalikan apa adanya kalau tak bisa di-parse.
function formatDate(v) {
	const d = new Date(String(v).replace(' ', 'T'))
	if (Number.isNaN(d.getTime())) return String(v)
	return d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
}

// Angka → "Rp 12.500.000" (id-ID). Kosong → "—".
function formatMoney(v) {
	if (v == null || v === '') return '—'
	const n = Number(v)
	if (Number.isNaN(n)) return String(v)
	return `Rp ${new Intl.NumberFormat('id-ID').format(n)}`
}

// Warna pill status (selaras `states` doctype Target dan Realisasi).
function statusPillClass(status) {
	switch (status) {
		case 'GAGAL BAYAR':
			return 'bg-ui-surface-red-50 text-ui-ink-red-600'
		case 'PARTIAL':
			return 'bg-ui-surface-orange-50 text-ui-ink-orange-600'
		case 'TARIKAN':
			return 'bg-ui-surface-pink-50 text-ui-ink-pink-600'
		case 'DONE':
			return 'bg-ui-surface-blue-50 text-ui-ink-blue-600'
		case 'BELUM JTO':
			return 'bg-ui-surface-cyan-50 text-ui-ink-cyan-600'
		default:
			return 'bg-ui-surface-gray-100 text-ui-ink-gray-600'
	}
}

// Warna titik status di sub-sheet pilih status.
function statusDotClass(status) {
	switch (status) {
		case 'GAGAL BAYAR':
			return 'border-ui-line-red-500'
		case 'PARTIAL':
			return 'border-ui-line-orange-500'
		case 'TARIKAN':
			return 'border-ui-line-pink-500'
		case 'DONE':
			return 'border-ui-line-blue-500'
		case 'BELUM JTO':
			return 'border-ui-line-cyan-500'
		default:
			return 'border-ui-line-gray-400'
	}
}

function restoreTargetState() {
	const saved = listPersistence.readSession({ filters: blankFilter() }).filters
	saved.status = saved.status.filter((value) => STATUS_LIST.value.includes(value))
	saved.sumber = saved.sumber.filter((value) => SUMBER_LIST.value.includes(value))
	saved.bucket = saved.bucket.filter((value) => BUCKET_LIST.value.includes(value))
	saved.pic_collector = saved.pic_collector.filter((value) => PIC_LIST.value.includes(value))
	Object.assign(appliedFilter, saved)
	const prefs = listPersistence.readPreferences({ sortDir: 'asc' })
	if (['asc', 'desc'].includes(prefs.sortDir)) sortDir.value = prefs.sortDir
}

onMounted(async () => {
	await refreshCsrfToken()
	await Promise.all([loadDoctypeMeta(), loadPicOptions()])
	restoreTargetState()
	restoreExpandedGroups()
	reload()
})
</script>

